import { HonoRequest } from '$C/src/request'
import { parseBody as headParse } from '$C/src/utils/body'
import { parseBody as baseParse } from './base-body'
import { Hono } from '$C/src/hono'
import { validator } from '$C/src/validator/validator'

const mkMultipart = () => {
  const d = new FormData()
  d.append('foo', 'bar')
  d.append('file', new File(['abc'], 'a.txt', { type: 'text/plain' }))
  return new Request('http://localhost/', { method: 'POST', body: d })
}
const mkUrlenc = () =>
  new Request('http://localhost/', {
    method: 'POST',
    body: new URLSearchParams({ foo: 'bar', baz: 'qux' }),
  })
const mkDup = () =>
  new Request('http://localhost/', {
    method: 'POST',
    body: 'foo=bar',
    headers: [
      ['Content-Type', 'application/x-www-form-urlencoded'],
      ['Content-Type', 'application/x-www-form-urlencoded'],
    ],
  })

const show = async (label: string, fn: () => Promise<unknown>) => {
  try {
    const r = await fn()
    console.log(label, '=> OK', JSON.stringify(r, (k, v) => (v instanceof File ? '[File ' + v.name + ']' : v)))
  } catch (e) {
    console.log(label, '=> THROW', (e as Error).name, (e as Error).message)
  }
}

for (const [name, parse] of [['BASE', baseParse], ['HEAD', headParse]] as const) {
  for (const [kind, mk] of [['multipart', mkMultipart], ['urlencoded', mkUrlenc]] as const) {
    await show(name + ' ' + kind + ' formData() then parseBody()', async () => {
      const req = new HonoRequest(mk())
      await req.formData()
      return parse(req)
    })
    await show(name + ' ' + kind + ' formData() then parseBody() then formData()', async () => {
      const req = new HonoRequest(mk())
      await req.formData()
      try { await parse(req) } catch {}
      const fd = await req.formData()
      return [...fd.keys()]
    })
    await show(name + ' ' + kind + ' parseBody() x2', async () => {
      const req = new HonoRequest(mk())
      await parse(req)
      return parse(req)
    })
    await show(name + ' ' + kind + ' text() then parseBody()', async () => {
      const req = new HonoRequest(mk())
      await req.text()
      return parse(req)
    })
    await show(name + ' ' + kind + ' blob() then parseBody()', async () => {
      const req = new HonoRequest(mk())
      await req.blob()
      return parse(req)
    })
    await show(name + ' ' + kind + ' arrayBuffer() then parseBody()', async () => {
      const req = new HonoRequest(mk())
      await req.arrayBuffer()
      return parse(req)
    })
    await show(name + ' ' + kind + ' parseBody() then text() length', async () => {
      const req = new HonoRequest(mk())
      await parse(req)
      return (await req.text()).length
    })
    await show(name + ' ' + kind + ' plain Request', async () => parse(mk()))
  }
  await show(name + ' duplicate Content-Type header', async () => {
    const r = mkDup()
    console.log('   header =', r.headers.get('Content-Type'))
    return parse(new HonoRequest(r))
  })
  await show(name + ' ws before semicolon', async () => {
    const src = mkMultipart()
    const ct = src.headers.get('Content-Type')!.replace('; boundary', ' ; boundary')
    return parse(new HonoRequest(new Request('http://localhost/', { method: 'POST', body: await src.arrayBuffer(), headers: { 'Content-Type': ct } })))
  })
  await show(name + ' Boundary param mixed-case name', async () => {
    const src = mkMultipart()
    const ct = src.headers.get('Content-Type')!.replace('multipart/form-data; boundary', 'Multipart/Form-Data; Boundary')
    return parse(new HonoRequest(new Request('http://localhost/', { method: 'POST', body: await src.arrayBuffer(), headers: { 'Content-Type': ct } })))
  })
  await show(name + ' malformed multipart', async () => {
    return parse(new HonoRequest(new Request('http://localhost/', { method: 'POST', body: 'garbage', headers: { 'Content-Type': 'multipart/form-data; boundary=xyz' } })))
  })
  await show(name + ' empty urlencoded body', async () => {
    return parse(new HonoRequest(new Request('http://localhost/', { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' } })))
  })
}

// HEAD app-level: middleware reads formData(), handler calls parseBody()
const app = new Hono()
app.post('/a', async (c, next) => { await c.req.formData(); await next() }, async (c) => c.json(await c.req.parseBody()))
app.post('/b', validator('form', (v) => v), async (c) => c.json({ v: c.req.valid('form'), p: await c.req.parseBody() }))
app.post('/c', async (c, next) => { await c.req.formData(); await next() }, validator('form', (v) => v), async (c) => c.json({ v: c.req.valid('form'), p: await c.req.parseBody() }))
for (const p of ['/a', '/b', '/c']) {
  for (const [kind, mk] of [['multipart', mkMultipart], ['urlencoded', mkUrlenc]] as const) {
    const src = mk()
    const res = await app.request(p, { method: 'POST', body: await src.arrayBuffer(), headers: { 'Content-Type': src.headers.get('Content-Type')! } })
    console.log('HEAD app', p, kind, res.status, (await res.text()).slice(0, 300))
  }
}
// validator json regex probes
const jsonApp = new Hono()
jsonApp.post('/', validator('json', (v) => v), (c) => c.json(c.req.valid('json')))
for (const ct of ['Application/JSON', 'APPLICATION/VND.API+JSON', 'application/json; Charset=UTF-8', 'Application/JSON ; charset=utf-8']) {
  const res = await jsonApp.request('/', { method: 'POST', body: '{"a":1}', headers: { 'Content-Type': ct } })
  console.log('HEAD json', ct, res.status, await res.text())
}
EOF
