    await run(\`\${kind} \${name} text()->parseBody\`, async () => { const r = await mk(kind); await r.text(); return parse(r) })
    // 3. parseBody then text()
    await run(\`\${kind} \${name} parseBody->text()\`, async () => { const r = await mk(kind); await parse(r); const t = await r.text(); return t.slice(0, 40) })
    // 4. parseBody twice
