export async function run(label: string, HonoRequest: any, Hono: any, parseBody: any) {
  const out: Record<string, unknown> = {}
  const show = (v: any) => JSON.stringify(v, (k, x) => (x instanceof File ? '[File]' : x))
  const mk = (kind: string, bodyOverride?: string) => {
    if (kind === 'multipart') {
      const fd = new FormData(); fd.append('foo', 'bar'); fd.append('baz', 'qux')
      return new Request('http://localhost/a', { method: 'POST', body: fd })
    }
    return new Request('http://localhost/a', {
      method: 'POST',
      body: bodyOverride ?? 'foo=bar&baz=qux',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    })
  }
  for (const kind of ['multipart', 'urlencoded']) {
    // direct HonoRequest: formData() then parseBody()
    const req = new HonoRequest(mk(kind))
    const fd = await req.formData()
    out[`${kind}: formData keys`] = [...fd.keys()]
    try { out[`${kind}: formData->parseBody`] = show(await parseBody(req)) } catch (e: any) { out[`${kind}: formData->parseBody`] = 'THROW ' + e?.name + ': ' + e?.message }
    try { out[`${kind}: then formData again`] = show([...(await req.formData()).keys()]) } catch (e: any) { out[`${kind}: then formData again`] = 'THROW ' + e?.name + ': ' + e?.message }
    // control: parseBody first
    const req2 = new HonoRequest(mk(kind))
    try { out[`${kind}: control parseBody only`] = show(await parseBody(req2)) } catch (e: any) { out[`${kind}: control`] = 'THROW ' + e?.message }
    // app-level
    const app = new Hono()
    app.post('/a', async (c: any, next: any) => { await c.req.formData(); await next() }, async (c: any) => c.json(await (label === 'HEAD' ? c.req.parseBody() : parseBody(c.req))))
    const res = await app.request(mk(kind))
    out[`${kind}: app status`] = res.status
    out[`${kind}: app body`] = (await res.text()).slice(0, 300)
  }
  // field-set mismatch
  const app = new Hono()
  app.post('/a', async (c: any, next: any) => {
    const fd = await c.req.formData()
    if (fd.has('role')) return c.text('forbidden field', 403)
    await next()
  }, async (c: any) => { const b = await (label === 'HEAD' ? c.req.parseBody() : parseBody(c.req)); return c.json({ role: b.role ?? null, keys: Object.keys(b) }) })
  const res = await app.request(mk('urlencoded', 'message=hi%26role%3Dadmin%26z%3D'))
  out['mismatch: status'] = res.status
  out['mismatch: body'] = (await res.text()).slice(0, 300)
  console.log(label, process.version)
  for (const [k, v] of Object.entries(out)) console.log('  ', k, '=>', v)
}
